import{_ as i,o as e,c as a,a8 as t}from"./chunks/framework.CNIpabDg.js";const c=JSON.parse(`{"title":"Run Xila with Docker","description":"Launch Xila's CLI shell or a WASI guest in a persistent headless Docker runtime.","frontmatter":{"layout":"doc","docType":"how-to","description":"Launch Xila's CLI shell or a WASI guest in a persistent headless Docker runtime."},"headers":[],"relativePath":"how-to/run-container-guest.md","filePath":"how-to/run-container-guest.md","lastUpdated":1793145952000}`),n={name:"how-to/run-container-guest.md"};function l(r,s,h,o,p,d){return e(),a("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[...s[0]||(s[0]=[t(`<h1 id="run-xila-with-docker" tabindex="-1">Run Xila with Docker <a class="header-anchor" href="#run-xila-with-docker" aria-label="Permalink to &quot;Run Xila with Docker&quot;">​</a></h1><p>The <code>ghcr.io/xila-project/xila-runtime</code> image <strong>runs Xila</strong>, instead of supplying build tools. You can open Xila&#39;s interactive command-line shell or run an existing <code>wasm32-wasip1</code> guest. This guide uses Docker on <strong>Linux/amd64</strong>. This image is headless: it does not provide the graphical desktop.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><ul><li>Install Docker and ensure you can start containers.</li><li>Use a published image from <a href="https://github.com/xila-project/platforms/actions/workflows/runtime.yml" target="_blank" rel="noreferrer">Platforms&#39; runtime workflow</a>. <code>latest</code> follows <code>main</code>; pin a release or commit-SHA tag for reproducible runs.</li><li>To run a guest, have a compatible <code>app.wasm</code> file compiled for <code>wasm32-wasip1</code>.</li></ul><h2 id="_1-pull-the-runtime-and-prepare-persistent-state" tabindex="-1">1. Pull the runtime and prepare persistent state <a class="header-anchor" href="#_1-pull-the-runtime-and-prepare-persistent-state" aria-label="Permalink to &quot;1. Pull the runtime and prepare persistent state&quot;">​</a></h2><p>From a <strong>host terminal</strong>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghcr.io/xila-project/xila-runtime:latest</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> volume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xila-state</span></span></code></pre></div><p>The named volume persists <code>/var/lib/xila/drive.img</code> between container runs. On its first start, Xila imports the image&#39;s reference filesystem; subsequent starts reuse the existing data and credentials. The image runs as non-root UID/GID <strong>10001</strong>.</p><h2 id="_2-launch-the-interactive-xila-shell" tabindex="-1">2. Launch the interactive Xila shell <a class="header-anchor" href="#_2-launch-the-interactive-xila-shell" aria-label="Permalink to &quot;2. Launch the interactive Xila shell&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> none</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --read-only</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --tmpfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp:rw,noexec,nosuid,size=16m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --mount</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> type=volume,src=xila-state,dst=/var/lib/xila</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ghcr.io/xila-project/xila-runtime:latest</span></span></code></pre></div><p>By default the image executes <code>xila-runtime shell --network=none</code>: this opens <strong>Xila&#39;s own command-line shell</strong>, not the container&#39;s Linux <code>bash</code>. On a fresh installation, log in as <strong>administrator</strong> with an empty password. Try <code>pwd</code> or <code>echo hello</code>, then <code>exit</code> to quit.</p><p>You may append <code>shell --network=none</code> after the image name to select this mode explicitly. The <code>-it</code> flags attach an interactive terminal, while Docker&#39;s <code>--network none</code> disables container networking independently of Xila&#39;s network setting.</p><h2 id="_3-run-an-existing-wasi-guest-instead" tabindex="-1">3. Run an existing WASI guest instead <a class="header-anchor" href="#_3-run-an-existing-wasi-guest-instead" aria-label="Permalink to &quot;3. Run an existing WASI guest instead&quot;">​</a></h2><p>From the <strong>host working directory</strong>, prepare the guest:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fixtures</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/app.wasm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fixtures/app.wasm</span></span></code></pre></div><p>Launch the guest with the same persistent disk:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> none</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --read-only</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --tmpfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp:rw,noexec,nosuid,size=16m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --mount</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> type=volume,src=xila-state,dst=/var/lib/xila</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --mount</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;type=bind,src=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/fixtures,dst=/mnt/xila/fixtures,readonly&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ghcr.io/xila-project/xila-runtime:latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --network=none</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --mount</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> host=/mnt/xila/fixtures,xila=/fixtures,ro</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /applications/executables/wasm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /fixtures/app.wasm</span></span></code></pre></div><p>The Docker bind mount exposes the file to the <strong>runtime process</strong>. The separate Xila <code>--mount</code> grants its VFS <strong>read-only</strong> access at <code>/fixtures</code>. Arguments after <code>app.wasm</code> go to the guest, and a nonzero guest exit status propagates to Docker.</p><h2 id="check-your-result" tabindex="-1">Check your result <a class="header-anchor" href="#check-your-result" aria-label="Permalink to &quot;Check your result&quot;">​</a></h2><p>In shell mode, confirm the login prompt works and a command executes inside Xila. In guest mode, inspect the application&#39;s output and exit code. The volume survives <code>--rm</code> and holds the existing disk; do not delete <code>xila-state</code> if it contains data you wish to keep.</p><p>For bind-mounted state instead of a named volume, grant write permission to UID/GID 10001. See the <a href="/reference/container-runtime.html">headless runtime reference</a> for disk/seed paths, additional read-write mounts, and explicit guest environment options.</p>`,21)])])}const u=i(n,[["render",l]]);export{c as __pageData,u as default};
